/**
 * TypeScript types for the task inbox — REQ-011.
 *
 * These types mirror the backend DTOs from REQ-010 workflow endpoints.
 * Designed for promotion into src/node/frontend/app/workflow/inbox/types.ts
 */

/** The five workflow document states from the backend enum. */
export type DocumentStatus =
  | "ricevuto"
  | "in_elaborazione"
  | "da_validare"
  | "validato"
  | "eccezione";

/** Task types matching backend WorkflowTask.task_type enum. */
export type TaskType = "validazione" | "eccezione";

/** Task status matching backend WorkflowTask.status enum. */
export type TaskStatus = "open" | "in_progress" | "completed" | "cancelled";

/** DTO returned by GET /api/tasks for each task row. */
export interface TaskDTO {
  /** Unique task identifier. */
  id: string;
  /** Associated document UUID. */
  document_id: string;
  /** Task classification. */
  task_type: TaskType;
  /** Current task status. */
  status: TaskStatus;
  /** Document workflow status for badge rendering. */
  document_status: DocumentStatus;
  /** Display name of assigned user, or null if unassigned. */
  assigned_to: string | null;
  /** ISO 8601 creation timestamp. */
  created_at: string;
  /** ISO 8601 completion timestamp, or null. */
  completed_at: string | null;
  /** Source filename for display context. */
  source_filename: string;
}

/** Response shape from GET /api/tasks. */
export interface TaskListResponse {
  tasks: TaskDTO[];
}

/** User auth context expected from shared auth (REQ-002/REQ-004). */
export interface AuthUser {
  id: string;
  display_name: string;
  permissions: string[];
}

