/**
 * API client functions for the task inbox — REQ-011.
 *
 * Uses the shared API base URL from environment.
 * Designed for promotion into src/node/frontend/app/workflow/inbox/api.ts
 */

import type { TaskListResponse } from "./types";

function getApiBase(): string {
  return (
    (typeof process !== "undefined" &&
      process.env?.NEXT_PUBLIC_API_BASE_URL) ||
    "http://localhost:8000"
  );
}

/**
 * Fetch open/in-progress tasks for the inbox.
 */
export async function fetchTasks(token?: string): Promise<TaskListResponse> {
  const headers: Record<string, string> = {
    Accept: "application/json",
  };
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  const res = await fetch(
    `${getApiBase()}/api/tasks?status=open,in_progress`,
    {
      method: "GET",
      headers,
    },
  );

  if (!res.ok) {
    throw new Error(`Errore nel caricamento dei task: ${res.status}`);
  }

  return res.json() as Promise<TaskListResponse>;
}

/**
 * Retry a document currently in eccezione state.
 */
export async function retryDocument(
  documentId: string,
  token?: string,
): Promise<void> {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
  };
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  const res = await fetch(
    `${getApiBase()}/api/documents/${documentId}/retry`,
    {
      method: "POST",
      headers,
    },
  );

  if (!res.ok) {
    throw new Error(`Errore nel tentativo di ripetizione: ${res.status}`);
  }
}

