/**
 * TanStack Query mutation hook for retrying an exception document — REQ-011.
 *
 * On success, invalidates the task list query to refresh the inbox.
 * Designed for promotion into src/node/frontend/app/workflow/inbox/hooks/useRetryTask.ts
 */

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { retryDocument } from "../api";
import { TASK_QUERY_KEY } from "./useTasks";

export function useRetryTask(token?: string) {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: (documentId: string) => retryDocument(documentId, token),
    onSuccess: () => {
      queryClient.invalidateQueries({
        queryKey: [...TASK_QUERY_KEY],
      });
    },
  });
}

