/**
 * Next.js page for the task inbox route — REQ-011.
 *
 * This is a client component that renders the TaskInbox.
 *
 * Auth context integration:
 *   At promotion time, the `useAuthUser` hook from `frontend.app.shared.auth`
 *   (REQ-002/REQ-004) replaces the placeholder below. The page already
 *   consumes the AuthUser interface so the swap is a single-line change.
 *
 * QueryClient:
 *   At promotion time, the QueryClientProvider should be lifted to a shared
 *   layout provider from `frontend.app.shared.query`. The local provider
 *   here ensures standalone page functionality until that shared provider
 *   is wired.
 *
 * Designed for promotion into src/node/frontend/app/workflow/inbox/page.tsx
 */

"use client";

import React from "react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { TaskInbox } from "./components/TaskInbox";
import type { AuthUser } from "./types";

// ---------------------------------------------------------------------------
// Auth context seam — replace with shared auth hook at promotion time.
//
// Example after promotion:
//   import { useAuthUser } from "@/shared/auth";
//   const { user, token } = useAuthUser();
//
// The placeholder below enables standalone rendering and testing.
// ---------------------------------------------------------------------------
function useAuthUser(): { user: AuthUser; token: string | undefined } {
  // TODO(REQ-002/REQ-004): Replace with shared auth context consumer.
  return {
    user: {
      id: "00000000-0000-0000-0000-000000000001",
      display_name: "Operatore",
      permissions: ["upload", "validate", "search", "export"],
    },
    token: undefined,
  };
}

// ---------------------------------------------------------------------------
// QueryClient — local instance until shared provider is available.
// ---------------------------------------------------------------------------
const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      retry: 1,
      refetchOnWindowFocus: true,
    },
  },
});

export default function InboxPage() {
  const { user, token } = useAuthUser();

  return (
    <QueryClientProvider client={queryClient}>
      <main className="mx-auto max-w-7xl px-4 py-8">
        <h1 className="mb-6 text-2xl font-bold text-gray-900">Inbox Task</h1>
        <TaskInbox user={user} token={token} />
      </main>
    </QueryClientProvider>
  );
}

