    task_type: "eccezione",
    status: "open",
    document_status: "eccezione",
    assigned_to: null,
    created_at: "2025-01-15T10:00:00Z",
    completed_at: null,
    source_filename: "contratto_scan.jpg",
  },
  {
    id: "task-003",
    document_id: "doc-aaaa-bbbb-cccc-dddd-eeeeeeee0003",
    task_type: "validazione",
    status: "in_progress",
    document_status: "in_elaborazione",
    assigned_to: "Giulia Bianchi",
    created_at: "2025-01-14T14:00:00Z",
    completed_at: null,
    source_filename: "report_q4.docx",
  },
];

// ---------------------------------------------------------------------------
// MSW Handlers
// ---------------------------------------------------------------------------

let fetchCount = 0;

export function resetFetchCount(): void {
  fetchCount = 0;
}

export function getFetchCount(): number {
  return fetchCount;
}

export const handlers = [
  http.get("*/api/tasks", () => {
    fetchCount++;
    const body: TaskListResponse = { tasks: TASK_FIXTURES };
    return HttpResponse.json(body);
  }),

  http.post("*/api/documents/:id/retry", ({ params }) => {
    const docId = params.id as string;
    const task = TASK_FIXTURES.find((t) => t.document_id === docId);
    if (!task || task.document_status !== "eccezione") {
      return HttpResponse.json(
        { detail: "Documento non in stato eccezione" },
        { status: 409 },
      );
    }
    return HttpResponse.json({ status: "retrying" }, { status: 200 });
  }),
];

export const server = setupServer(...handlers);

// ---------------------------------------------------------------------------
