/**
 * StateBadge component tests — REQ-011.
 *
 * Proves acceptance criterion:
 *   "State badges reflect the five workflow states consistently with backend values"
 *
 * @vitest-environment jsdom
 */

import React from "react";
import { describe, it, expect } from "vitest";
import { render, screen } from "@testing-library/react";
import "@testing-library/jest-dom";
import { StateBadge } from "../../../src/node/frontend/app/workflow/inbox/components/StateBadge";
import type { DocumentStatus } from "../../../src/node/frontend/app/workflow/inbox/types";

const STATE_EXPECTATIONS: Array<{
  status: DocumentStatus;
  label: string;
  colorFragment: string;
}> = [
  { status: "ricevuto", label: "Ricevuto", colorFragment: "bg-blue" },
  {
    status: "in_elaborazione",
    label: "In elaborazione",
    colorFragment: "bg-yellow",
  },
  { status: "da_validare", label: "Da validare", colorFragment: "bg-orange" },
  { status: "validato", label: "Validato", colorFragment: "bg-green" },
  { status: "eccezione", label: "Eccezione", colorFragment: "bg-red" },
];

describe("StateBadge", () => {
  it.each(STATE_EXPECTATIONS)(
    "renders $status with Italian label '$label' and $colorFragment color",
    ({ status, label, colorFragment }) => {
      render(<StateBadge status={status} />);

      const badge = screen.getByTestId(`badge-${status}`);
      expect(badge).toBeInTheDocument();
      expect(badge).toHaveTextContent(label);
      expect(badge.className).toContain(colorFragment);
    },
  );

  it("renders all five states without errors", () => {
    const { container } = render(
      <>
        {STATE_EXPECTATIONS.map(({ status }) => (
          <StateBadge key={status} status={status} />
        ))}
      </>,
    );

    expect(container.querySelectorAll("span")).toHaveLength(5);
  });

  it("falls back gracefully for unknown status", () => {
    // @ts-expect-error — testing unknown status
    render(<StateBadge status="sconosciuto" />);
    const badge = screen.getByTestId("badge-sconosciuto");
    expect(badge).toHaveTextContent("sconosciuto");
    expect(badge.className).toContain("bg-gray");
  });
});

