/**
 * TaskInbox component tests — REQ-011.
 *
 * Proves all five acceptance criteria:
 * 1. Dashboard inbox lists open tasks with document_id, task type, task status, creation time, and assignment
 * 2. State badges reflect the five workflow states consistently with backend values
 * 3. Users can open document detail directly from a task row
 * 4. Retry action is shown only for permitted exception tasks
 * 5. Read state and list refresh update without full page reload
 *
 * All tests are synchronous-friendly (no real timers, no async polling waits).
 * MSW intercepts all network calls.
 *
 * @vitest-environment jsdom
 */

import React from "react";
import {
  describe,
  it,
  expect,
  beforeAll,
  afterAll,
  afterEach,
} from "vitest";
import { render, screen, waitFor, fireEvent } from "@testing-library/react";
import "@testing-library/jest-dom";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { TaskInbox } from "../../../src/node/frontend/app/workflow/inbox/components/TaskInbox";
import type { AuthUser } from "../../../src/node/frontend/app/workflow/inbox/types";
import {
  server,
  TASK_FIXTURES,
  emptyHandlers,
  errorHandlers,
  resetFetchCount,
  getFetchCount,
} from "./setup";

// ---------------------------------------------------------------------------
// Next.js Link mock — avoids requiring full Next.js runtime in vitest/jsdom.
// Renders a plain <a> with the same props so href assertions work.
// ---------------------------------------------------------------------------
/* eslint-disable @typescript-eslint/no-explicit-any */
import { vi } from "vitest";
vi.mock("next/link", () => ({
  __esModule: true,
  default: ({
    href,
    children,
    ...rest
  }: {
    href: string;
    children: React.ReactNode;
    [key: string]: any;
  }) =>
    React.createElement("a", { href, ...rest }, children),
}));
/* eslint-enable @typescript-eslint/no-explicit-any */

// ---------------------------------------------------------------------------
// MSW lifecycle
// ---------------------------------------------------------------------------

beforeAll(() => server.listen({ onUnhandledRequest: "error" }));
afterEach(() => {
  server.resetHandlers();
  localStorage.clear();
  resetFetchCount();
});
afterAll(() => server.close());

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

const USER_WITH_VALIDATE: AuthUser = {
  id: "user-001",
  display_name: "Mario Rossi",
  permissions: ["upload", "validate", "search"],
};

const USER_WITHOUT_VALIDATE: AuthUser = {
  id: "user-002",
  display_name: "Luca Verdi",
  permissions: ["upload", "search"],
};

function renderInbox(user: AuthUser = USER_WITH_VALIDATE) {
  const queryClient = new QueryClient({
    defaultOptions: {
      queries: { retry: false, gcTime: 0, staleTime: 0 },
    },
  });

  return render(
    <QueryClientProvider client={queryClient}>
      <TaskInbox user={user} />
    </QueryClientProvider>,
  );
}

// ---------------------------------------------------------------------------
// AC-1: Dashboard inbox lists open tasks with required columns
// ---------------------------------------------------------------------------

describe("AC-1: task list with required columns", () => {
  it("renders all tasks from the API with document_id, task type, status, creation time, and assignment", async () => {
    renderInbox();

    await waitFor(() => {
      expect(screen.getByTestId("task-inbox")).toBeInTheDocument();
    });

    // Verify each task row is present
    for (const task of TASK_FIXTURES) {
      const row = screen.getByTestId(`task-row-${task.id}`);
      expect(row).toBeInTheDocument();

      // Document ID (truncated)
      expect(row).toHaveTextContent(task.document_id.slice(0, 8));

      // Source filename
      expect(row).toHaveTextContent(task.source_filename);
    }

    // Verify column headers in Italian
    expect(screen.getByText("Documento")).toBeInTheDocument();
    expect(screen.getByText("Tipo task")).toBeInTheDocument();
    expect(screen.getByText("Stato")).toBeInTheDocument();
    expect(screen.getByText("Creato il")).toBeInTheDocument();
    expect(screen.getByText("Assegnato a")).toBeInTheDocument();
  });

  it("shows loading state in Italian", () => {
    renderInbox();
    expect(screen.getByTestId("inbox-loading")).toHaveTextContent(
      "Caricamento task in corso",
    );
  });

  it("shows empty state when no tasks exist", async () => {
    server.use(...emptyHandlers);
    renderInbox();

    await waitFor(() => {
      expect(screen.getByTestId("inbox-empty")).toBeInTheDocument();
    });

    expect(screen.getByTestId("inbox-empty")).toHaveTextContent(
      "Nessun task in attesa",
    );
  });

  it("shows error state in Italian on API failure", async () => {
    server.use(...errorHandlers);
    renderInbox();

    await waitFor(() => {
      expect(screen.getByTestId("inbox-error")).toBeInTheDocument();
    });

    expect(screen.getByTestId("inbox-error")).toHaveTextContent(
      "Errore nel caricamento dei task",
    );
  });
});

// ---------------------------------------------------------------------------
// AC-2: State badges (covered in StateBadge.test.tsx, integration check here)
// ---------------------------------------------------------------------------

describe("AC-2: state badges in inbox rows", () => {
  it("renders correct badge for each task document status", async () => {
    renderInbox();

    await waitFor(() => {
      expect(screen.getByTestId("task-inbox")).toBeInTheDocument();
    });

    // task-001 is da_validare
    expect(screen.getByTestId("badge-da_validare")).toHaveTextContent(
      "Da validare",
    );

    // task-002 is eccezione
    expect(screen.getByTestId("badge-eccezione")).toHaveTextContent(
      "Eccezione",
    );

    // task-003 is in_elaborazione
    expect(screen.getByTestId("badge-in_elaborazione")).toHaveTextContent(
      "In elaborazione",
    );
  });
});

// ---------------------------------------------------------------------------
// AC-3: Users can open document detail directly from a task row
// ---------------------------------------------------------------------------

describe("AC-3: navigates to document detail", () => {
  it("each task row contains a client-side link to /documents/{document_id}", async () => {
    renderInbox();

    await waitFor(() => {
      expect(screen.getByTestId("task-inbox")).toBeInTheDocument();
    });

    for (const task of TASK_FIXTURES) {
      const link = screen.getByTestId(
        `detail-link-${task.id}`,
      ) as HTMLAnchorElement;
      expect(link).toBeInTheDocument();
      expect(link.tagName).toBe("A");
      expect(link.getAttribute("href")).toBe(
        `/documents/${task.document_id}`,
      );
    }
  });
});

// ---------------------------------------------------------------------------
// AC-4: Retry action shown only for permitted exception tasks
// ---------------------------------------------------------------------------

describe("AC-4: retry button visibility", () => {
  it("shows retry button for exception task when user has validate permission", async () => {
    renderInbox(USER_WITH_VALIDATE);

    await waitFor(() => {
      expect(screen.getByTestId("task-inbox")).toBeInTheDocument();
    });

    // task-002 is eccezione — should show retry
    expect(screen.getByTestId("retry-btn-task-002")).toBeInTheDocument();
    expect(screen.getByTestId("retry-btn-task-002")).toHaveTextContent(
      "Riprova",
    );

    // task-001 is validazione/da_validare — should NOT show retry
    expect(
      screen.queryByTestId("retry-btn-task-001"),
    ).not.toBeInTheDocument();

    // task-003 is validazione/in_elaborazione — should NOT show retry
    expect(
      screen.queryByTestId("retry-btn-task-003"),
    ).not.toBeInTheDocument();
  });

  it("hides retry button when user lacks validate permission", async () => {
    renderInbox(USER_WITHOUT_VALIDATE);

    await waitFor(() => {
      expect(screen.getByTestId("task-inbox")).toBeInTheDocument();
    });

    // No retry buttons at all
    expect(
      screen.queryByTestId("retry-btn-task-002"),
    ).not.toBeInTheDocument();
  });

  it("retry button triggers API call and refreshes list", async () => {
    renderInbox(USER_WITH_VALIDATE);

    await waitFor(() => {
      expect(screen.getByTestId("task-inbox")).toBeInTheDocument();
    });

    const initialFetches = getFetchCount();

    const retryBtn = screen.getByTestId("retry-btn-task-002");
    fireEvent.click(retryBtn);

    // After retry, the query should be invalidated and refetched.
    // MSW will serve the same fixture, but the mutation should complete
    // without error and trigger a cache invalidation (new fetch).
    await waitFor(() => {
      expect(screen.queryByTestId("retry-error")).not.toBeInTheDocument();
      expect(getFetchCount()).toBeGreaterThan(initialFetches);
    });
  });
});

// ---------------------------------------------------------------------------
// AC-5: Read state and refresh without full page reload
// ---------------------------------------------------------------------------

describe("AC-5: read state and refresh without reload", () => {
  it("marks a task as read on row click and persists to localStorage", async () => {
    renderInbox();

    await waitFor(() => {
      expect(screen.getByTestId("task-inbox")).toBeInTheDocument();
    });

    const row = screen.getByTestId("task-row-task-001");

    // Initially not read — should have font-semibold
    expect(row.className).toContain("font-semibold");

    // Click to mark as read
    fireEvent.click(row);

    await waitFor(() => {
      expect(row.className).toContain("opacity-70");
      expect(row.className).not.toContain("font-semibold");
    });

    // Verify localStorage persistence
    const stored = JSON.parse(
      localStorage.getItem("zen2030_read_tasks") ?? "[]",
    );
    expect(stored).toContain("task-001");
  });

  it("restores read state from localStorage on mount", async () => {
    // Pre-populate localStorage
    localStorage.setItem(
      "zen2030_read_tasks",
      JSON.stringify(["task-001"]),
    );

    renderInbox();

    await waitFor(() => {
      expect(screen.getByTestId("task-inbox")).toBeInTheDocument();
    });

    const row = screen.getByTestId("task-row-task-001");
    expect(row.className).toContain("opacity-70");
  });

  it("data-updated-at timestamp proves TanStack Query fetched data without page reload", async () => {
    renderInbox();

    await waitFor(() => {
      expect(screen.getByTestId("task-inbox")).toBeInTheDocument();
    });

    // The hidden data-updated-at element is rendered by TaskInbox
    // and contains the TanStack Query dataUpdatedAt timestamp.
    // A non-zero value proves data was fetched via the query hook
    // (SPA-style) rather than a full page load.
    const updatedAt = screen.getByTestId("data-updated-at");
    expect(updatedAt).toBeInTheDocument();
    const ts = Number(updatedAt.textContent);
    expect(ts).toBeGreaterThan(0);

    // Verify tasks are rendered (data came from query fetch)
    expect(screen.getByTestId("task-row-task-001")).toBeInTheDocument();
    expect(screen.getByTestId("task-row-task-002")).toBeInTheDocument();
    expect(screen.getByTestId("task-row-task-003")).toBeInTheDocument();
  });

  it("query cache invalidation after retry triggers refetch without page reload", async () => {
    renderInbox(USER_WITH_VALIDATE);

    await waitFor(() => {
      expect(screen.getByTestId("task-inbox")).toBeInTheDocument();
    });

    const tsBefore = Number(
      screen.getByTestId("data-updated-at").textContent,
    );
    const fetchesBefore = getFetchCount();

    // Trigger retry — this invalidates the query cache
    fireEvent.click(screen.getByTestId("retry-btn-task-002"));

    await waitFor(() => {
      // A new fetch must have occurred
      expect(getFetchCount()).toBeGreaterThan(fetchesBefore);
    });

    // The component is still mounted (no page reload) and shows fresh data
    const tsAfter = Number(
      screen.getByTestId("data-updated-at").textContent,
    );
    expect(tsAfter).toBeGreaterThanOrEqual(tsBefore);
    expect(screen.getByTestId("task-inbox")).toBeInTheDocument();
  });
});

