/**
 * TanStack Query hook for fetching the task list — REQ-011.
 *
 * Polls every 30 seconds for background refresh without full page reload.
 * Designed for promotion into src/node/frontend/app/workflow/inbox/hooks/useTasks.ts
 */

import { useQuery } from "@tanstack/react-query";
import { fetchTasks } from "../api";
import type { TaskListResponse } from "../types";

export const TASK_QUERY_KEY = ["workflow", "tasks", "inbox"] as const;
export const POLL_INTERVAL_MS = 30_000;

export function useTasks(token?: string) {
  return useQuery<TaskListResponse>({
    queryKey: [...TASK_QUERY_KEY],
    queryFn: () => fetchTasks(token),
    refetchInterval: POLL_INTERVAL_MS,
    refetchIntervalInBackground: false,
    staleTime: 10_000,
  });
}
