/**
 * Custom hook for tracking read state of inbox tasks — REQ-011.
 *
 * Persists read task IDs to localStorage so visual state survives
 * component remounts without a full page reload.
 *
 * Designed for promotion into src/node/frontend/app/workflow/inbox/hooks/useReadState.ts
 */

import { useState, useEffect, useCallback } from "react";

const READ_TASKS_KEY = "zen2030_read_tasks";

function loadReadIds(): Set<string> {
  if (typeof window === "undefined") return new Set();
  try {
    const raw = localStorage.getItem(READ_TASKS_KEY);
    return raw ? new Set(JSON.parse(raw) as string[]) : new Set();
  } catch {
    return new Set();
  }
}

function persistReadIds(ids: Set<string>): void {
  if (typeof window === "undefined") return;
  try {
    localStorage.setItem(READ_TASKS_KEY, JSON.stringify([...ids]));
  } catch {
    // localStorage unavailable — degrade gracefully
  }
}

export function useReadState() {
  const [readIds, setReadIds] = useState<Set<string>>(new Set());

  useEffect(() => {
    setReadIds(loadReadIds());
  }, []);

  const markRead = useCallback((taskId: string) => {
    setReadIds((prev) => {
      const next = new Set(prev);
      next.add(taskId);
      persistReadIds(next);
      return next;
    });
  }, []);

  const isRead = useCallback(
    (taskId: string) => readIds.has(taskId),
    [readIds],
  );

  return { readIds, markRead, isRead } as const;
}
