/**
 * TaskRow — renders a single task in the inbox table.
 *
 * Shows document_id, task type, status badge, creation time, assignment.
 * Conditionally renders retry button for exception tasks when user has permission.
 * Tracks read state via callback.
 * Uses Next.js Link for client-side navigation (no full page reload).
 *
 * Designed for promotion into src/node/frontend/app/workflow/inbox/components/TaskRow.tsx
 */

"use client";

import React from "react";
import Link from "next/link";
import { StateBadge } from "./StateBadge";
import type { TaskDTO } from "../types";

interface TaskRowProps {
  task: TaskDTO;
  canRetry: boolean;
  isRead: boolean;
  isRetrying: boolean;
  onRetry: (documentId: string) => void;
  onMarkRead: (taskId: string) => void;
}

const TASK_TYPE_LABELS: Record<string, string> = {
  validazione: "Validazione",
  eccezione: "Eccezione",
};

function formatDate(iso: string): string {
  try {
    return new Intl.DateTimeFormat("it-IT", {
      dateStyle: "short",
      timeStyle: "short",
    }).format(new Date(iso));
  } catch {
    return iso;
  }
}

export function TaskRow({
  task,
  canRetry,
  isRead,
  isRetrying,
  onRetry,
  onMarkRead,
}: TaskRowProps) {
  const handleRowClick = () => {
    onMarkRead(task.id);
  };

  const showRetry =
    canRetry &&
    task.task_type === "eccezione" &&
    task.document_status === "eccezione";

  return (
    <tr
      data-testid={`task-row-${task.id}`}
      className={`border-b hover:bg-gray-50 cursor-pointer ${isRead ? "opacity-70" : "font-semibold"}`}
      onClick={handleRowClick}
    >
      <td className="px-4 py-3">
        <Link
          href={`/documents/${task.document_id}`}
          data-testid={`detail-link-${task.id}`}
          className="text-blue-600 hover:underline"
          onClick={(e) => e.stopPropagation()}
        >
          {task.document_id.slice(0, 8)}…
        </Link>
      </td>
      <td className="px-4 py-3 text-sm text-gray-600">
        {task.source_filename}
      </td>
      <td className="px-4 py-3">
        {TASK_TYPE_LABELS[task.task_type] ?? task.task_type}
      </td>
      <td className="px-4 py-3">
        <StateBadge status={task.document_status} />
      </td>
      <td className="px-4 py-3 text-sm">{formatDate(task.created_at)}</td>
      <td className="px-4 py-3 text-sm">
        {task.assigned_to ?? <span className="text-gray-400">—</span>}
      </td>
      <td className="px-4 py-3">
        {showRetry && (
          <button
            data-testid={`retry-btn-${task.id}`}
            type="button"
            disabled={isRetrying}
            className="rounded bg-red-600 px-3 py-1 text-xs text-white hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-500 disabled:opacity-50"
            onClick={(e) => {
              e.stopPropagation();
              onRetry(task.document_id);
            }}
          >
            {isRetrying ? "In corso…" : "Riprova"}
          </button>
        )}
      </td>
    </tr>
  );
}
