/**
 * TaskInbox — main inbox container listing open workflow tasks.
 *
 * Uses TanStack Query for data fetching with polling.
 * Tracks read state via useReadState hook (localStorage persistence).
 * Italian labels throughout.
 *
 * Designed for promotion into src/node/frontend/app/workflow/inbox/components/TaskInbox.tsx
 */

"use client";

import React, { useCallback, useMemo } from "react";
import { TaskRow } from "./TaskRow";
import { useTasks } from "../hooks/useTasks";
import { useRetryTask } from "../hooks/useRetryTask";
import { useReadState } from "../hooks/useReadState";
import type { AuthUser } from "../types";

interface TaskInboxProps {
  user: AuthUser;
  token?: string;
}

export function TaskInbox({ user, token }: TaskInboxProps) {
  const { data, isLoading, isError, error, dataUpdatedAt } = useTasks(token);
  const retryMutation = useRetryTask(token);
  const { readIds, markRead, isRead } = useReadState();

  const canRetry = useMemo(
    () => user.permissions.includes("validate"),
    [user.permissions],
  );

  const handleRetry = useCallback(
    (documentId: string) => {
      retryMutation.mutate(documentId);
    },
    [retryMutation],
  );

  if (isLoading) {
    return (
      <div
        data-testid="inbox-loading"
        className="p-8 text-center text-gray-500"
      >
        Caricamento task in corso…
      </div>
    );
  }

  if (isError) {
    return (
      <div
        data-testid="inbox-error"
        className="p-8 text-center text-red-600"
      >
        Errore nel caricamento dei task:{" "}
        {error instanceof Error ? error.message : "Errore sconosciuto"}
      </div>
    );
  }

  const tasks = data?.tasks ?? [];

  if (tasks.length === 0) {
    return (
      <div
        data-testid="inbox-empty"
        className="p-8 text-center text-gray-500"
      >
        Nessun task in attesa.
      </div>
    );
  }

  return (
    <div data-testid="task-inbox" className="overflow-x-auto">
      <table className="min-w-full divide-y divide-gray-200">
        <thead className="bg-gray-50">
          <tr>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase text-gray-500">
              Documento
            </th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase text-gray-500">
              File
            </th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase text-gray-500">
              Tipo task
            </th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase text-gray-500">
              Stato
            </th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase text-gray-500">
              Creato il
            </th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase text-gray-500">
              Assegnato a
            </th>
            <th className="px-4 py-3 text-left text-xs font-medium uppercase text-gray-500">
              Azioni
            </th>
          </tr>
        </thead>
        <tbody className="divide-y divide-gray-200 bg-white">
          {tasks.map((task) => (
            <TaskRow
              key={task.id}
              task={task}
              canRetry={canRetry}
              isRead={isRead(task.id)}
              isRetrying={
                retryMutation.isPending &&
                retryMutation.variables === task.document_id
              }
              onRetry={handleRetry}
              onMarkRead={markRead}
            />
          ))}
        </tbody>
      </table>
      {retryMutation.isError && (
        <div data-testid="retry-error" className="mt-2 text-sm text-red-600">
          Errore durante il tentativo di ripetizione.
        </div>
      )}
      {/* Hidden timestamp for test assertions on data freshness */}
      <span
        data-testid="data-updated-at"
        className="sr-only"
        aria-hidden="true"
      >
        {dataUpdatedAt}
      </span>
    </div>
  );
}
